# NexGen Home Page Upgrade - Corporate Premium with Stock Photos
# Downloads 6 images + applies redesigned home page
# Usage: powershell -ExecutionPolicy Bypass -File apply-homepage-upgrade.ps1

 $ErrorActionPreference = "Stop"
Set-Location "C:\Users\T\nexgenfinancialexperts"
Write-Host "=== NexGen Home Page Upgrade ===" -ForegroundColor Cyan

# 1. Download images
Write-Host ""
Write-Host "[1/2] Downloading stock images..." -ForegroundColor White
 $images = @(
    @{ Name = "hero-professional.jpg"; Url = "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/8cfd0b01eb96.jpg" },
    @{ Name = "office-building.jpg";   Url = "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/b638220bf687.jpg" },
    @{ Name = "business-meeting.jpg";  Url = "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/17742062d2a1.png" },
    @{ Name = "tax-documents.jpg";     Url = "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/6aa963b2d2ea.jpg" },
    @{ Name = "entrepreneur.jpg";      Url = "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/cdf5cf4ae0f9.jpg" },
    @{ Name = "handshake.jpg";         Url = "https://z-cdn.chatglm.cn/image-search-mcp/images-ppt/5962a55af0cc.jpg" }
)
 $imgDir = "public\images"
if (-not (Test-Path $imgDir)) { New-Item -ItemType Directory -Path $imgDir -Force | Out-Null }
foreach ($img in $images) {
    $path = Join-Path $imgDir $img.Name
    Write-Host "  $($img.Name): " -NoNewline
    try {
        Invoke-WebRequest -Uri $img.Url -OutFile $path -UseBasicParsing -TimeoutSec 30
        Write-Host "OK" -ForegroundColor Green
    } catch {
        Write-Host "FAILED" -ForegroundColor Red
    }
}

# 2. Decompress and save page.tsx
Write-Host ""
Write-Host "[2/2] Applying new home page..." -ForegroundColor White
 $b64 = ""
 $gzBytes = [System.Convert]::FromBase64String($b64)
 $ms = New-Object System.IO.MemoryStream(,$gzBytes)
 $gz = New-Object System.IO.Compression.GZipStream($ms,[System.IO.Compression.CompressionMode]::Decompress)
 $sr = New-Object System.IO.StreamReader($gz)
 $content = $sr.ReadToEnd()
 $sr.Close(); $gz.Close(); $ms.Close()
[System.IO.File]::WriteAllText((Resolve-Path "src\app\page.tsx").Path, $content, [System.Text.UTF8Encoding]::new($false))
Write-Host "  OK: page.tsx updated ($($content.Length) chars)" -ForegroundColor Green

Write-Host ""
Write-Host "========================================" -ForegroundColor Cyan
Write-Host "DONE - Now commit and push:" -ForegroundColor Green
Write-Host "========================================" -ForegroundColor Cyan
Write-Host "  git add -A" -ForegroundColor White
Write-Host "  git commit -m 'design: upgrade home page'" -ForegroundColor White
Write-Host "  git pull --rebase" -ForegroundColor White
Write-Host "  git push" -ForegroundColor White